window.AUTH=window.AUTH||{};window.AUTH["99-1823"]={"d":"99-1823","id":"2001/99-1823","n":"Equal Employment Opportunity Commission v. Waffle House, Inc.","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the petitioner","date":"","url":"https://www.justice.gov/osg/media/233541/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/eeoc-v-waffle-house-inc-brief-merits","n":56}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep534/usrep534279/usrep534279.pdf","tr":false,"items":[{"t":"case","label":"AT&T Techs., Inc. v. Communications Workers","cite":"475 U.S. 643","y":1986,"id":"1985/84-1913","sc":1,"sum":"The issue whether, because of express exclusion or other evidence, the dispute over interpretation of Article 20 was subject to the arbitration clause, should have been decided by the District Court and reviewed by the Court of Appeals, and should not have been referred to the arbitrator.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Albemarle Paper Co. v. Moody","cite":"422 U.S. 405","y":1975,"id":"1974/74-389","sc":1,"op":1,"sum":"The Court held that backpay should be awarded based on a court’s discretion. The decision in this case should be considered in light of the goals of the Equal Employment Opportunity Act. Because the prospect of a backpay award could ensure the use of equal employment practices, it serves the purposes of the Act and should be awarded in this case.","sumSrc":"Oyez","by":{"0":"13, 31, 37"}},{"t":"case","label":"Alden v. Maine","cite":"527 U.S. 706","y":1999,"id":"1998/98-436","sc":1,"sum":"A sharply divided court held in a 5-4 decision that Congress may not use its Article I powers to abrogate the states' sovereign immunity. Both the terms and history of the eleventh amendment suggest that States are immune from suits in their own courts.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Alexander v. Gardner-Denver Co.","cite":"415 U.S. 36","y":1974,"id":"1973/72-5847","sc":1,"sum":"An employee's statutory right to trial de novo under Title VII of the Civil Rights Act of 1964 is not foreclosed by prior submission of his claim to final arbitration under the nondiscrimination clause of a collective-bargaining.agreement.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Armendariz v. Foundation Health Psychcare Servs., Inc.","cite":"6 P.3d 669","y":2000,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/6/669/","by":{"0":"16"}},{"t":"case","label":"Blim v. Western Elec. Co.","cite":"731 F.2d 1473","y":1984,"url":"https://www.courtlistener.com/c/F.2d/731/1473/","by":{"0":"32"}},{"t":"case","label":"Board of Trustees of the Univ. of Ala. v. Garrett","cite":"121 S. Ct. 955","y":2001,"id":"2000/99-1240","sc":1,"op":1,"sum":"The Court held that suits in federal court by state employees to recover money damages by reason of the state's failure to comply with Title I of the ADA are barred by the Eleventh Amendment.","sumSrc":"Oyez","by":{"0":"15, 41"}},{"t":"case","label":"Circuit City Stores, Inc. v. Adams","cite":"121 S. Ct. 1302","y":2001,"id":"2000/99-1379","sc":1,"op":2,"sum":"The Court held that section 1 exemption is confined to transportation workers. \"The wording of [section 1] calls for the application of the maxim ejusdem generis, the statutory canon that 'where general words follow specific words in a statutory enumeration, the general words are construed to embrace only objects similar in nature to those objects enumerated by the preceding specific words,'\" wrote Justice Kennedy.","sumSrc":"Oyez","by":{"0":"14, 36, 40"}},{"t":"case","label":"City of Newport v. Fact Concerts, Inc.","cite":"453 U.S. 247","y":1981,"id":"1980/80-396","sc":1,"op":1,"sum":"Respondents (an organization licensed by petitioner city to present certain musical concerts, and a promoter of the concerts) brought suit in Federal District Court against the city and city officials. Alleging, inter alia, that the city's cancellation of the license amounted to a violation of their constitutional rights under color of.state law, repondents sought compensatory and punitive damages under 42 U. S. C. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Cole v. Burns Int’l Sec. Servs.","cite":"105 F.3d 1465","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/105/1465/","by":{"0":"16"}},{"t":"case","label":"Donovan v. Cunningham","cite":"716 F.2d 1455","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/716/1455/","by":{"0":"33"}},{"t":"case","label":"Duffield v. Robertson Stephens & Co.","cite":"144 F.3d 1182","y":1998,"url":"https://www.courtlistener.com/c/F.3d/144/1182/","by":{"0":"16"}},{"t":"case","label":"EEOC v. Frank’s Nursery & Crafts, Inc.","cite":"177 F.3d 448","y":1999,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/177/448/","op":1,"by":{"0":"39"}},{"t":"case","label":"EEOC v. General Elec. Co.","cite":"532 F.2d 359","y":1976,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/532/359/","by":{"0":"36"}},{"t":"case","label":"EEOC v. Goodyear Aerospace Corp.","cite":"813 F.2d 1539","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/813/1539/","op":3,"by":{"0":"39"}},{"t":"case","label":"EEOC v. Harris Chernin, Inc.","cite":"10 F.3d 1286","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/10/1286/","op":1,"by":{"0":"39"}},{"t":"case","label":"EEOC v. Hernando Bank, Inc.","cite":"724 F.2d 1188","y":1984,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/724/1188/","by":{"0":"20-21"}},{"t":"case","label":"EEOC v. Johnson & Higgins, Inc.","cite":"91 F.3d 1529","y":1996,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/91/1529/","by":{"0":"20"}},{"t":"case","label":"EEOC v. Kidder, Peabody & Co.","cite":"156 F.3d 298","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/156/298/","op":1,"sum":"Stating that EEOC’s public enforcement role and the FAA represent “competing public interests”.","sumSrc":"brief:0","by":{"0":"23, 29"}},{"t":"case","label":"EEOC v. United States Steel Corp.","cite":"921 F.2d 489","y":1990,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/921/489/","op":1,"sum":"Noting distinctions between ADEA enforcement scheme and scheme applicable to Title VII and ADA cases.","sumSrc":"brief:0","by":{"0":"39"}},{"t":"case","label":"EEOC v. Wal-Mart Stores, Inc.","cite":"187 F.3d 1241","y":1999,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/187/1241/","by":{"0":"36"}},{"t":"case","label":"General Tel. Co. of the N.W., Inc. v. EEOC","cite":"446 U.S. 318","y":1980,"id":"1979/79-488","sc":1,"op":7,"sum":"The EEOC may seek classwide relief under § 706 (f) (1) without being certified as the class representative under Rule 23.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Gilmer v. Interstate/Johnson Lane Corp.","cite":"500 U.S. 20","y":1991,"id":"1990/90-18","sc":1,"op":10,"sum":"Holding that a claim arising under the Age Discrimination in Employment Act of 1967 (ADEA), 29 U. S. C. § 621 et seq. (1994 ed.), may be subject to compulsory arbitration.","sumSrc":"opinion","by":{"0":"8, 15, 22, 31, 40, 41"}},{"t":"case","label":"Green Tree Fin. Corp. v. Randolph","cite":"121 S. Ct. 513","y":2000,"id":"2000/99-1235","sc":1,"sum":"The Court held that an order compelling arbitration pursuant to the parties' agreement is a \"final decision with respect to an arbitration\" within the meaning of the Federal Arbitration Act making it immediately appealable pursuant to the FAA.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Herman v. South Carolina Nat’l Bank","cite":"140 F.3d 1413","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/140/1413/","by":{"0":"33"}},{"t":"case","label":"Landgraf v. USI Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"McKennon v. Nashville Banner Publ’g Co.","cite":"513 U.S. 352","y":1995,"id":"1994/93-1543","sc":1,"op":1,"sum":"Alleging that her discharge by respondent Nashville Banner Publishing Company violated the Age Discrimination in Employment Act of 1967 (ADEA), petitioner McKennon filed suit seeking a variety of legal and equitable remedies available under the ADEA, including backpay. After she admitted in her deposition that she had copied several of the Banner's confidential documents during her final year of employment, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31, 36"}},{"t":"case","label":"Mitsubishi Motors Corp. v. Soler Chrysler-Plymouth, Inc.","cite":"473 U.S. 614","y":1985,"id":"1984/83-1569","sc":1,"op":3,"sum":"The Supreme Court held that claims arising under the Sherman Act and encompassed in a valid arbitration clause in an international commercial transaction are arbitrable under the federal Arbitration Act. Justice John Paul Stevens dissented, arguing that a fair construction of the arbitration clause does not encompass antitrust claims.","sumSrc":"Oyez","by":{"0":"22, 24"}},{"t":"case","label":"Phelps Dodge Corp. v. NLRB","cite":"313 U.S. 177","y":1941,"id":"scdb/1940-080","sc":1,"by":{"0":"31"}},{"t":"case","label":"Rodriguez de Quijas v. Shearson/American Express, Inc.","cite":"490 U.S. 477","y":1989,"id":"1988/88-385","sc":1,"sum":"A predispute agreement to arbitrate claims under the Securities Act of 1933 is enforceable and resolution of the claims only in a judicial forum is not required.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Scherk v. Alberto-Culver Co.","cite":"417 U.S. 506","y":1974,"id":"1973/73-781","sc":1,"op":1,"sum":"Noting that one purpose of the FAA is to place arbitration agreements \"'upon the same footing as other contracts' (citation omitted).","sumSrc":"opinion","by":{"0":"22"}},{"t":"case","label":"Secretary of Labor v. Fitzsimmons","cite":"805 F.2d 682","y":1986,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/805/682/","by":{"0":"33"}},{"t":"case","label":"Tony & Susan Alamo Found. v. Secretary of Labor","cite":"471 U.S. 290","y":1985,"id":"1984/83-1935","sc":1,"sum":"Petitioner Foundation is a nonprofit religious organization that derives its income largely from the operation of commercial businesses staffed by the Foundation's \"associates,\" most of whom were drug addicts, derelicts, or criminals before their rehabilitation by the Foundation. These workers receive no cash salaries, but the Foundation provides them with food, clothing, shelter, and other benefits. The Secretary …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"United States v. N.L. Indus., Inc.","cite":"479 F.2d 354","y":1973,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/479/354/","by":{"0":"31"}},{"t":"case","label":"United States v. W.T. Grant Co.","cite":"345 U.S. 629","y":1953,"id":"scdb/1952-095","sc":1,"sum":"Under § 15 of the Clayton Act, the United States sued in a federal district court to enjoin an individual and six corporations from violating § 8 through the holding by the individual of interlocking directorates in three pairs of competing corporations. Thereafter, the individual resigned his directorship in one out of each pair of corporatiQns and filed affidavits disclaiming any intention of resuming such …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36"}},{"t":"case","label":"United Steelworkers v. Warrior & Gulf Navigation Co.","cite":"363 U.S. 574","y":1960,"id":"1959/443","sc":1,"sum":"It erred in doing so, and the judgment is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Wright v. Universal Mar. Serv. Corp.","cite":"525 U.S. 70","y":1998,"id":"1998/97-889","sc":1,"sum":"Announced by Justice Antonin Scalia, the Court ruled that the CBA's arbitration clause did not require Wright to use the arbitration procedure for the alleged violation of the ADA. In his opinion, Scalia wrote that the CBA did not contain a waiver of the employee's right to a judicial forum for federal claims of employment discrimination.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","stext":{"head":"§621. Congressional statement of findings and purpose","paras":[[0,"(a) The Congress hereby finds and declares that—"],[1,"(1) in the face of rising productivity and affluence, older workers find themselves disadvantaged in their efforts to retain employment, and especially to regain employment when displaced from jobs;"],[1,"(2) the setting of arbitrary age limits regardless of potential for job performance has become a common practice, and certain otherwise desirable practices may work to the disadvantage of older persons;"],[1,"(3) the incidence of unemployment, especially long-term unemployment with resultant deterioration of skill, morale, and employer acceptability is, relative to the younger ages, high among older workers; their numbers are great and growing; and their employment problems grave;"],[1,"(4) the existence in industries affecting commerce, of arbitrary discrimination in employment because of age, burdens commerce and the free flow of goods in commerce."],[0,"(b) It is therefore the purpose of this chapter to promote employment of older persons based on their ability rather than age; to prohibit arbitrary age discrimination in employment; to help employers and workers find ways of meeting problems arising from the impact of age on employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/621?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§621. Congressional statement of findings and purpose","tname":"Labor","by":{"0":"40"}},{"t":"usc","label":"42 U.S.C. § 12101","url":"https://www.law.cornell.edu/uscode/text/42/12101","stext":{"head":"§12101. Findings and purpose","paras":[[0,"(a) Findings"],[0,"The Congress finds that—"],[1,"(1) physical or mental disabilities in no way diminish a person's right to fully participate in all aspects of society, yet many people with physical or mental disabilities have been precluded from doing so because of discrimination; others who have a record of a disability or are regarded as having a disability also have been subjected to discrimination;"],[1,"(2) historically, society has tended to isolate and segregate individuals with disabilities, and, despite some improvements, such forms of discrimination against individuals with disabilities continue to be a serious and pervasive social problem;"],[1,"(3) discrimination against individuals with disabilities persists in such critical areas as employment, housing, public accommodations, education, transportation, communication, recreation, institutionalization, health services, voting, and access to public services;"],[1,"(4) unlike individuals who have experienced discrimination on the basis of race, color, sex, national origin, religion, or age, individuals who have experienced discrimination on the basis of disability have often had no legal recourse to redress such discrimination;"],[1,"(5) individuals with disabilities continually encounter various forms of discrimination, including outright intentional exclusion, the discriminatory effects of architectural, transportation, and communication barriers, overprotective rules and policies, failure to make modifications to existing facilities and practices, exclusionary qualification standards and criteria, segregation, and relegation to lesser services, programs, activities, benefits, jobs, or other opportunities;"],[1,"(6) census data, national polls, and other studies have documented that people with disabilities, as a group, occupy an inferior status in our society, and are severely disadvantaged socially, vocationally, economically, and educationally;"],[1,"(7) the Nation's proper goals regarding individuals with disabilities are to assure equality of opportunity, full participation, independent living, and economic self-sufficiency for such individuals; and"],[1,"(8) the continuing existence of unfair and unnecessary discrimination and prejudice denies people with disabilities the opportunity to compete on an equal basis and to pursue those opportunities for which our free society is justifiably famous, and costs the United States billions of dollars in unnecessary expenses resulting from dependency and nonproductivity."],[0,"(b) Purpose"],[0,"It is the purpose of this chapter—"],[1,"(1) to provide a clear and comprehensive national mandate for the elimination of discrimination against individuals with disabilities;"],[1,"(2) to provide clear, strong, consistent, enforceable standards addressing discrimination against individuals with disabilities;"],[1,"(3) to ensure that the Federal Government plays a central role in enforcing the standards established in this chapter on behalf of individuals with disabilities; and"],[1,"(4) to invoke the sweep of congressional authority, including the power to enforce the fourteenth amendment and to regulate commerce, in order to address the major areas of discrimination faced day-to-day by people with disabilities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12101?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§12101. Findings and purpose","tname":"The Public Health and Welfare","by":{"0":"42, 42"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":18,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"0":"passim, 42"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(a)","(b)","(g)","(g)(1)"],"stext":{"head":"§2000e–5. Enforcement provisions","paras":[[0,"(a) Power of Commission to prevent unlawful employment practices"],[0,"The Commission is empowered, as hereinafter provided, to prevent any person from engaging in any unlawful employment practice as set forth in section 2000e–2 or 2000e–3 of this title."],[0,"(b) Charges by persons aggrieved or member of Commission of unlawful employment practices by employers, etc.; filing; allegations; notice to respondent; contents of notice; investigation by Commission; contents of charges; prohibition on disclosure of charges; determination of reasonable cause; conference, conciliation, and persuasion for elimination of unlawful practices; prohibition on disclosure of informal endeavors to end unlawful practices; use of evidence in subsequent proceedings; penalties for disclosure of information; time for determination of reasonable cause"],[0,"Whenever a charge is filed by or on behalf of a person claiming to be aggrieved, or by a member of the Commission, alleging that an employer, employment agency, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs, has engaged in an unlawful employment practice, the Commission shall serve a notice of the charge (including the date, place and circumstances of the alleged unlawful employment practice) on such employer, employment agency, labor organization, or joint labor-management committee (hereinafter referred to as the \"respondent\") within ten days, and shall make an investigation thereof. Charges shall be in writing under oath or affirmation and shall contain such information and be in such form as the Commission requires. Charges shall not be made public by the Commission. If the Commission determines after such investigation that there is not reasonable cause to believe that the charge is true, it shall dismiss the charge and promptly notify the person claiming to be aggrieved and the respondent of its action. In determining whether reasonable cause exists, the Commission shall accord substantial weight to final findings and orders made by State or local authorities in proceedings commenced under State or local law pursuant to the requirements of subsections (c) and (d). If the Commission determines after such investigation that there is reasonable cause to believe that the charge is true, the Commission shall endeavor to eliminate any such alleged unlawful employment practice by informal methods of conference, conciliation, and persuasion. Nothing said or done during and as a part of such informal endeavors may be made public by the Commission, its officers or employees, or used as evidence in a subsequent proceeding without the written consent of the persons concerned. Any person who makes public information in violation of this subsection shall be fined not more than $1,000 or imprisoned for not more than one year, or both. The Commission shall make its determination on reasonable cause as promptly as possible and, so far as practicable, not later than one hundred and twenty days from the filing of the charge or, where applicable under subsection (c) or (d), from the date upon which the Commission is authorized to take action with respect to the charge."],[0,"(c) State or local enforcement proceedings; notification of State or local authority; time for filing charges with Commission; commencement of proceedings"],[0,"In the case of an alleged unlawful employment practice occurring in a State, or political subdivision of a State, which has a State or local law prohibiting the unlawful employment practice alleged and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, no charge may be filed under subsection (a) 1 by the person aggrieved before the expiration of sixty days after proceedings have been commenced under the State or local law, unless such proceedings have been earlier terminated, provided that such sixty-day period shall be extended to one hundred and twenty days during the first year after the effective date of such State or local law. If any requirement for the commencement of such proceedings is imposed by a State or local authority other than a requirement of the filing of a written and signed statement of the facts upon which the proceeding is based, the proceeding shall be deemed to have been commenced for the purposes of this subsection at the time such statement is sent by registered mail to the appropriate State or local authority."],[0,"(d) State or local enforcement proceedings; notification of State or local authority; time for action on charges by Commission"],[0,"In the case of any charge filed by a member of the Commission alleging an unlawful employment practice occurring in a State or political subdivision of a State which has a State or local law prohibiting the practice alleged and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, the Commission shall, before taking any action with respect to such charge, notify the appropriate State or local officials and, upon request, afford them a reasonable time, but not less than sixty days (provided that such sixty-day period shall be extended to one hundred and twenty days during the first year after the effective day of such State or local law), unless a shorter period is requested, to act under such State or local law to remedy the practice alleged."],[0,"(e) Time for filing charges; time for service of notice of charge on respondent; filing of charge by Commission with State or local agency; seniority system"],[0,"(1) A charge under this section shall be filed within one hundred and eighty days after the alleged unlawful employment practice occurred and notice of the charge (including the date, place and circumstances of the alleged unlawful employment practice) shall be served upon the person against whom such charge is made within ten days thereafter, except that in a case of an unlawful employment practice with respect to which the person aggrieved has initially instituted proceedings with a State or local agency with authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, such charge shall be filed by or on behalf of the person aggrieved within three hundred days after the alleged unlawful employment practice occurred, or within thirty days after receiving notice that the State or local agency has terminated the proceedings under the State or local law, whichever is earlier, and a copy of such charge shall be filed by the Commission with the State or local agency."],[0,"(2) For purposes of this section, an unlawful employment practice occurs, with respect to a seniority system that has been adopted for an intentionally discriminatory purpose in violation of this subchapter (whether or not that discriminatory purpose is apparent on the face of the seniority provision), when the seniority system is adopted, when an individual becomes subject to the seniority system, or when a person aggrieved is injured by the application of the seniority system or provision of the system."],[0,"(3)(A) For purposes of this section, an unlawful employment practice occurs, with respect to discrimination in compensation in violation of this subchapter, when a discriminatory compensation decision or other practice is adopted, when an individual becomes subject to a discriminatory compensation decision or other practice, or when an individual is affected by application of a discriminatory compensation decision or other practice, including each time wages, benefits, or other compensation is paid, resulting in whole or in part from such a decision or other practice."],[0,"(B) In addition to any relief authorized by section 1981a of this title, liability may accrue and an aggrieved person may obtain relief as provided in subsection (g)(1), including recovery of back pay for up to two years preceding the filing of the charge, where the unlawful employment practices that have occurred during the charge filing period are similar or related to unlawful employment practices with regard to discrimination in compensation that occurred outside the time for filing a charge."],[0,"(f) Civil action by Commission, Attorney General, or person aggrieved; preconditions; procedure; appointment of attorney; payment of fees, costs, or security; intervention; stay of Federal proceedings; action for appropriate temporary or preliminary relief pending final disposition of charge; jurisdiction and venue of United States courts; designation of judge to hear and determine case; assignment of case for hearing; expedition of case; appointment of master"],[0,"(1) If within thirty days after a charge is filed with the Commission or within thirty days after expiration of any period of reference under subsection (c) or (d), the Commission has been unable to secure from the respondent a conciliation agreement acceptable to the Commission, the Commission may bring a civil action against any respondent not a government, governmental agency, or political subdivision named in the charge. In the case of a respondent which is a government, governmental agency, or political subdivision, if the Commission has been unable to secure from the respondent a conciliation agreement acceptable to the Commission, the Commission shall take no further action and shall refer the case to the Attorney General who may bring a civil action against such respondent in the appropriate United States district court. The person or persons aggrieved shall have the right to intervene in a civil action brought by the Commission or the Attorney General in a case involving a government, governmental agency, or political subdivision. If a charge filed with the Commission pursuant to subsection (b), is dismissed by the Commission, or if within one hundred and eighty days from the filing of such charge or the expiration of any period of reference under subsection (c) or (d), whichever is later, the Commission has not filed a civil action under this section or the Attorney General has not filed a civil action in a case involving a government, governmental agency, or political subdivision, or the Commission has not entered into a conciliation agreement to which the person aggrieved is a party, the Commission, or the Attorney General in a case involving a government, governmental agency, or political subdivision, shall so notify the person aggrieved and within ninety days after the giving of such notice a civil action may be brought against the respondent named in the charge (A) by the person claiming to be aggrieved or (B) if such charge was filed by a member of the Commission, by any person whom the charge alleges was aggrieved by the alleged unlawful employment practice. Upon application by the complainant and in such circumstances as the court may deem just, the court may appoint an attorney for such complainant and may authorize the commencement of the action without the payment of fees, costs, or security. Upon timely application, the court may, in its discretion, permit the Commission, or the Attorney General in a case involving a government, governmental agency, or political subdivision, to intervene in such civil action upon certification that the case is of general public importance. Upon request, the court may, in its discretion, stay further proceedings for not more than sixty days pending the termination of State or local proceedings described in subsection (c) or (d) of this section or further efforts of the Commission to obtain voluntary compliance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-5?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§2000e–5. Enforcement provisions","tname":"The Public Health and Welfare","by":{"0":"3, 17, 3, 20, 22, 3, 4, 17, 20, 22, 25, 4, 21, 4, 17, 18, 4, 17, 39"}},{"t":"usc","label":"42 U.S.C. § 2000e-6","url":"https://www.law.cornell.edu/uscode/text/42/2000e-6","subs":["(1970)","(c)"],"stext":{"head":"§2000e–6. Civil actions by the Attorney General","paras":[[0,"(a) Complaint"],[0,"Whenever the Attorney General has reasonable cause to believe that any person or group of persons is engaged in a pattern or practice of resistance to the full enjoyment of any of the rights secured by this subchapter, and that the pattern or practice is of such a nature and is intended to deny the full exercise of the rights herein described, the Attorney General may bring a civil action in the appropriate district court of the United States by filing with it a complaint (1) signed by him (or in his absence the Acting Attorney General), (2) setting forth facts pertaining to such pattern or practice, and (3) requesting such relief, including an application for a permanent or temporary injunction, restraining order or other order against the person or persons responsible for such pattern or practice, as he deems necessary to insure the full enjoyment of the rights herein described."],[0,"(b) Jurisdiction; three-judge district court for cases of general public importance: hearing, determination, expedition of action, review by Supreme Court; single judge district court: hearing, determination, expedition of action"],[0,"The district courts of the United States shall have and shall exercise jurisdiction of proceedings instituted pursuant to this section, and in any such proceeding the Attorney General may file with the clerk of such court a request that a court of three judges be convened to hear and determine the case. Such request by the Attorney General shall be accompanied by a certificate that, in his opinion, the case is of general public importance. A copy of the certificate and request for a three-judge court shall be immediately furnished by such clerk to the chief judge of the circuit (or in his absence, the presiding circuit judge of the circuit) in which the case is pending. Upon receipt of such request it shall be the duty of the chief judge of the circuit or the presiding circuit judge, as the case may be, to designate immediately three judges in such circuit, of whom at least one shall be a circuit judge and another of whom shall be a district judge of the court in which the proceeding was instituted, to hear and determine such case, and it shall be the duty of the judges so designated to assign the case for hearing at the earliest practicable date, to participate in the hearing and determination thereof, and to cause the case to be in every way expedited. An appeal from the final judgment of such court will lie to the Supreme Court."],[0,"In the event the Attorney General fails to file such a request in any such proceeding, it shall be the duty of the chief judge of the district (or in his absence, the acting chief judge) in which the case is pending immediately to designate a judge in such district to hear and determine the case. In the event that no judge in the district is available to hear and determine the case, the chief judge of the district, or the acting chief judge, as the case may be, shall certify this fact to the chief judge of the circuit (or in his absence, the acting chief judge) who shall then designate a district or circuit judge of the circuit to hear and determine the case."],[0,"It shall be the duty of the judge designated pursuant to this section to assign the case for hearing at the earliest practicable date and to cause the case to be in every way expedited."],[0,"(c) Transfer of functions, etc., to Commission; effective date; prerequisite to transfer; execution of functions by Commission"],[0,"Effective two years after March 24, 1972, the functions of the Attorney General under this section shall be transferred to the Commission, together with such personnel, property, records, and unexpended balances of appropriations, allocations, and other funds employed, used, held, available, or to be made available in connection with such functions unless the President submits, and neither House of Congress vetoes, a reorganization plan pursuant to chapter 9 of title 5, inconsistent with the provisions of this subsection. The Commission shall carry out such functions in accordance with subsections (d) and (e) of this section."],[0,"(d) Transfer of functions, etc., not to affect suits commenced pursuant to this section prior to date of transfer"],[0,"Upon the transfer of functions provided for in subsection (c) of this section, in all suits commenced pursuant to this section prior to the date of such transfer, proceedings shall continue without abatement, all court orders and decrees shall remain in effect, and the Commission shall be substituted as a party for the United States of America, the Attorney General, or the Acting Attorney General, as appropriate."],[0,"(e) Investigation and action by Commission pursuant to filing of charge of discrimination; procedure"],[0,"Subsequent to March 24, 1972, the Commission shall have authority to investigate and act on a charge of a pattern or practice of discrimination, whether filed by or on behalf of a person claiming to be aggrieved or by a member of the Commission. All such actions shall be conducted in accordance with the procedures set forth in section 2000e–5 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-6?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2000e–6. Civil actions by the Attorney General","tname":"The Public Health and Welfare","by":{"0":"28, 37"}},{"t":"usc","label":"42 U.S.C. § 1981a","url":"https://www.law.cornell.edu/uscode/text/42/1981a","subs":["(a)(1)","(a)(2)","(d)(1)(A)","(d)(1)(B)"],"stext":{"head":"§1981a. Damages in cases of intentional discrimination in employment","paras":[[0,"(a) Right of recovery"],[0,"(1) Civil rights"],[1,"In an action brought by a complaining party under section 706 or 717 of the Civil Rights Act of 1964 [42 U.S.C. 2000e–5, 2000e–16] against a respondent who engaged in unlawful intentional discrimination (not an employment practice that is unlawful because of its disparate impact) prohibited under section 703, 704, or 717 of the Act [42 U.S.C. 2000e–2, 2000e–3, 2000e–16], and provided that the complaining party cannot recover under section 1981 of this title, the complaining party may recover compensatory and punitive damages as allowed in subsection (b), in addition to any relief authorized by section 706(g) of the Civil Rights Act of 1964, from the respondent."],[0,"(2) Disability"],[1,"In an action brought by a complaining party under the powers, remedies, and procedures set forth in section 706 or 717 of the Civil Rights Act of 1964 [42 U.S.C. 2000e–5, 2000e–16] (as provided in section 107(a) of the Americans with Disabilities Act of 1990 (42 U.S.C. 12117(a)), and section 794a(a)(1) of title 29, respectively) against a respondent who engaged in unlawful intentional discrimination (not an employment practice that is unlawful because of its disparate impact) under section 791 of title 29 and the regulations implementing section 791 of title 29, or who violated the requirements of section 791 of title 29 or the regulations implementing section 791 of title 29 concerning the provision of a reasonable accommodation, or section 102 of the Americans with Disabilities Act of 1990 (42 U.S.C. 12112), or committed a violation of section 102(b)(5) of the Act, against an individual, the complaining party may recover compensatory and punitive damages as allowed in subsection (b), in addition to any relief authorized by section 706(g) of the Civil Rights Act of 1964, from the respondent."],[0,"(3) Reasonable accommodation and good faith effort"],[1,"In cases where a discriminatory practice involves the provision of a reasonable accommodation pursuant to section 102(b)(5) of the Americans with Disabilities Act of 1990 [42 U.S.C. 12112(b)(5)] or regulations implementing section 791 of title 29, damages may not be awarded under this section where the covered entity demonstrates good faith efforts, in consultation with the person with the disability who has informed the covered entity that accommodation is needed, to identify and make a reasonable accommodation that would provide such individual with an equally effective opportunity and would not cause an undue hardship on the operation of the business."],[0,"(b) Compensatory and punitive damages"],[0,"(1) Determination of punitive damages"],[1,"A complaining party may recover punitive damages under this section against a respondent (other than a government, government agency or political subdivision) if the complaining party demonstrates that the respondent engaged in a discriminatory practice or discriminatory practices with malice or with reckless indifference to the federally protected rights of an aggrieved individual."],[0,"(2) Exclusions from compensatory damages"],[1,"Compensatory damages awarded under this section shall not include backpay, interest on backpay, or any other type of relief authorized under section 706(g) of the Civil Rights Act of 1964 [42 U.S.C. 2000e–5(g)]."],[0,"(3) Limitations"],[1,"The sum of the amount of compensatory damages awarded under this section for future pecuniary losses, emotional pain, suffering, inconvenience, mental anguish, loss of enjoyment of life, and other nonpecuniary losses, and the amount of punitive damages awarded under this section, shall not exceed, for each complaining party—"],[2,"(A) in the case of a respondent who has more than 14 and fewer than 101 employees in each of 20 or more calendar weeks in the current or preceding calendar year, $50,000;"],[2,"(B) in the case of a respondent who has more than 100 and fewer than 201 employees in each of 20 or more calendar weeks in the current or preceding calendar year, $100,000; and"],[2,"(C) in the case of a respondent who has more than 200 and fewer than 501 employees in each of 20 or more calendar weeks in the current or preceding calendar year, $200,000; and"],[2,"(D) in the case of a respondent who has more than 500 employees in each of 20 or more calendar weeks in the current or preceding calendar year, $300,000."],[0,"(4) Construction"],[1,"Nothing in this section shall be construed to limit the scope of, or the relief available under, section 1981 of this title."],[0,"(c) Jury trial"],[0,"If a complaining party seeks compensatory or punitive damages under this section—"],[1,"(1) any party may demand a trial by jury; and"],[1,"(2) the court shall not inform the jury of the limitations described in subsection (b)(3)."],[0,"(d) Definitions"],[0,"As used in this section:"],[0,"(1) Complaining party"],[1,"The term \"complaining party\" means—"],[2,"(A) in the case of a person seeking to bring an action under subsection (a)(1), the Equal Employment Opportunity Commission, the Attorney General, or a person who may bring an action or proceeding under title VII of the Civil Rights Act of 1964 (42 U.S.C. 2000e et seq.); or"],[2,"(B) in the case of a person seeking to bring an action under subsection (a)(2), the Equal Employment Opportunity Commission, the Attorney General, a person who may bring an action or proceeding under section 794a(a)(1) of title 29, or a person who may bring an action or proceeding under title I of the Americans with Disabilities Act of 1990 [42 U.S.C. 12111 et seq.]."],[0,"(2) Discriminatory practice"],[1,"The term \"discriminatory practice\" means the discrimination described in paragraph (1), or the discrimination or the violation described in paragraph (2), of subsection (a)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1981a?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1981a. Damages in cases of intentional discrimination in employment","tname":"The Public Health and Welfare","by":{"0":"4, 18, 5, 18, 5, 19, 5, 19"}},{"t":"usc","label":"9 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/9/1","stext":{"head":"§1. \"Maritime transactions\" and \"commerce\" defined; exceptions to operation of title","paras":[[0,"\"Maritime transactions\", as herein defined, means charter parties, bills of lading of water carriers, agreements relating to wharfage, supplies furnished vessels or repairs to vessels, collisions, or any other matters in foreign commerce which, if the subject of controversy, would be embraced within admiralty jurisdiction; \"commerce\", as herein defined, means commerce among the several States or with foreign nations, or in any Territory of the United States or in the District of Columbia, or between any such Territory and another, or between any such Territory and any State or foreign nation, or between the District of Columbia and any State or Territory or foreign nation, but nothing herein contained shall apply to contracts of employment of seamen, railroad employees, or any other class of workers engaged in foreign or interstate commerce."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/9/1?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1. \"Maritime transactions\" and \"commerce\" defined; exceptions to operation of title","tname":"Arbitration","by":{"0":"9"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","by":{"0":"29"}}]};